    <section ref={ref} className="relative h-[260vh] overflow-x-clip">
      <div className="sticky top-16 h-[calc(100vh-4rem)] overflow-hidden px-8">
        <motion.div
          style={{ opacity: copyOpacity, y: copyY }}
