          <motion.p
            style={{ opacity: captionOpacity }}
            className="absolute inset-x-0 bottom-0 z-20 text-center text-xs text-muted-foreground"
          >
            {caption}
          </motion.p>
        )}
      </div>
    </section>
  );
}

