      className={`relative grid overflow-hidden rounded-3xl border border-border bg-card lg:sticky lg:min-h-[28rem] lg:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)] ${
        isLast ? "" : "mb-8 lg:mb-[35vh]"
      }`}
    >
      <div className="flex flex-col justify-center p-6 sm:p-10">
        <p className="font-mono text-xs uppercase tracking-[0.16em] text-primary">
          {String(index + 1).padStart(2, "0")} · {card.eyebrow}
        </p>
        <h3 className="mt-3 text-2xl font-semibold tracking-tight text-foreground sm:text-3xl">
          {card.title}
        </h3>
        <p className="mt-3 max-w-md text-sm leading-6 text-secondary sm:text-base">
          {card.desc}
        </p>
      </div>
      <div
        aria-hidden="true"
        inert
        className="relative min-h-64 border-t border-border bg-background lg:border-l lg:border-t-0"
      >
        <Visual />
      </div>
      {/* Dims the card as the next one covers it. */}
      <motion.span
        aria-hidden="true"
        style={{ opacity: shade }}
        className="pointer-events-none absolute inset-0 bg-background"
      />
    </motion.article>
  );
}

signatures.morphing-tabs:
"use client";

import { useId, useRef, useState } from "react";
import { AnimatePresence, motion, useInView } from "framer-motion";
import { useLoopingStages } from "./useLoopingStages";
import { useMotionStill } from "./MotionPreference";

/**
 * Feature tabs that run themselves. The active marker slides between tabs,
 * a thin bar shows time left on the current one, and the demo slides in from
 * the side of the tab that was chosen. It stops looping for good once the
 * visitor picks a tab.
 *
 * heading:    node shown above
 * features:   [{ id, label, title, desc, Demo }]
 *             Demo is a component that shows the feature working.
 * durationMs: time on each tab while it loops
 */
export default function MorphingTabs({ heading, features, durationMs = 5200 }) {
  const ref = useRef(null);
  const marker = useId();
  const inView = useInView(ref, { amount: 0.4 });
  const still = useMotionStill();
  const { stage, select } = useLoopingStages({
    count: features.length,
    durationMs,
    inView,
    stopOnSelect: true,
  });
  // Adjusting state during render is React's pattern for tracking a previous value.
  const [previous, setPrevious] = useState(stage);
  const [direction, setDirection] = useState(1);
  if (stage !== previous) {
    setDirection(stage > previous ? 1 : -1);
    setPrevious(stage);
  }
  const active = features[stage];
  const Demo = active.Demo;

  const moveFocus = (event, index) => {
    const step = { ArrowRight: 1, ArrowLeft: -1 }[event.key];
    if (!step) return;
    event.preventDefault();
    const next = (index + step + features.length) % features.length;
    select(next);
    event.currentTarget.parentElement.children[next]?.focus();
  };

  return (
    <section
      ref={ref}
      className="relative mx-auto max-w-6xl px-4 py-24 sm:px-6 lg:px-8 lg:py-32"
    >
      {heading}

      <div
        role="tablist"
        aria-label="Features"
        className="mt-10 flex gap-1 overflow-x-auto rounded-2xl border border-border bg-card p-1"
      >
        {features.map((feature, index) => {
          const isActive = index === stage;
          return (
            <button
              key={feature.id}
              type="button"
              role="tab"
              id={`${marker}-tab-${index}`}
              aria-selected={isActive}
              aria-controls={`${marker}-panel`}
              tabIndex={isActive ? 0 : -1}
              onClick={() => select(index)}
              onKeyDown={(event) => moveFocus(event, index)}
              className={`relative min-h-11 flex-1 whitespace-nowrap rounded-xl px-4 text-sm font-medium transition-colors duration-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary ${
                isActive ? "text-foreground" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {isActive && (
                <motion.span
                  layoutId={marker}
                  transition={{ type: "spring", stiffness: 380, damping: 32 }}
                  className="absolute inset-0 overflow-hidden rounded-xl bg-background"
                >
                  {!still && (
                    <motion.span
                      key={stage}
                      initial={{ scaleX: 0 }}
                      animate={{ scaleX: 1 }}
                      transition={{ duration: durationMs / 1000, ease: "linear" }}
                      style={{ originX: 0 }}
                      className="absolute inset-x-0 bottom-0 h-0.5 bg-primary"
                    />
                  )}
                </motion.span>
              )}
              <span className="relative">{feature.label}</span>
            </button>
          );
        })}
      </div>

      <div
        id={`${marker}-panel`}
        role="tabpanel"
        aria-labelledby={`${marker}-tab-${stage}`}
        className="relative mt-4 grid overflow-hidden rounded-3xl border border-border bg-card lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)]"
      >
        <AnimatePresence mode="wait" initial={false} custom={direction}>
          <motion.div
            key={active.id}
            custom={direction}
            variants={{
              enter: (dir) => ({ opacity: 0, x: dir * 40 }),
              center: { opacity: 1, x: 0 },
              exit: (dir) => ({ opacity: 0, x: dir * -40 }),
            }}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ duration: 0.28, ease: [0.22, 1, 0.36, 1] }}
            className="col-span-full grid lg:grid-cols-subgrid"
          >
            <div className="p-6 sm:p-10">
              <h3 className="text-2xl font-semibold tracking-tight text-foreground">
                {active.title}
              </h3>
              <p className="mt-3 text-sm leading-6 text-secondary sm:text-base">
                {active.desc}
              </p>
            </div>
            <div
              aria-hidden="true"
              inert
              className="relative min-h-72 border-t border-border bg-background lg:border-l lg:border-t-0"
            >
              <Demo />
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
    </section>
  );
}

signatures.bento-grid:
"use client";

import { motion } from "framer-motion";

// Spans on the 6-column desktop grid. Mix sizes; never use one size for all.
const SIZES = {
  hero: "lg:col-span-4 lg:row-span-2",
  tall: "lg:col-span-2 lg:row-span-2",
  wide: "lg:col-span-4",
  half: "lg:col-span-3",
  small: "lg:col-span-2",
};

// Each tile enters from the side it sits on, so the grid assembles inwards
// instead of every tile fading up the same way.
const FROM = {
  left: { x: -28, y: 0 },
  right: { x: 28, y: 0 },
  below: { x: 0, y: 28 },
};

/**
 * An uneven grid of feature tiles, each holding a small live scene instead of
 * an icon. Tiles assemble inwards when seen. Scenes can react to hover with
 * Tailwind group-hover classes, because every tile is a group.
 *
 * heading: node shown above
 * tiles:   [{ id, size, from, title, desc, Scene }]
 *          size: hero | tall | wide | half | small
 *          from: left | right | below, the side the tile sits on
 *          Scene: a component; loop it with nx- CSS classes so the pause
 *          button stops it, and keep it under 7 seconds
 */
export default function BentoGrid({ heading, tiles }) {
  return (
    <section className="relative mx-auto max-w-7xl px-4 py-24 sm:px-6 lg:px-8 lg:py-32">
      {heading}
      <div className="mt-12 grid auto-rows-[minmax(15rem,auto)] gap-4 sm:grid-cols-2 lg:grid-cols-6">
        {tiles.map((tile, index) => {
          const Scene = tile.Scene;
          const from = FROM[tile.from] ?? FROM.below;
          return (
            <motion.article
              key={tile.id}
              data-reveal
              initial={{ opacity: 0, ...from }}
              whileInView={{ opacity: 1, x: 0, y: 0 }}
              viewport={{ once: true, amount: 0.25 }}
              transition={{ type: "spring", stiffness: 200, damping: 22, delay: index * 0.06 }}
              className={`group relative flex flex-col overflow-hidden rounded-3xl border border-border bg-card transition-colors duration-300 hover:border-primary/60 ${
                SIZES[tile.size] ?? SIZES.small
              }`}
            >
              <div aria-hidden="true" inert className="relative min-h-36 flex-1">
                <Scene />
              </div>
              <div className="border-t border-border p-5">
                <h3 className="text-base font-semibold text-foreground">{tile.title}</h3>
                <p className="mt-1 text-sm leading-6 text-secondary">{tile.desc}</p>
              </div>
            </motion.article>
          );
        })}
      </div>
    </section>
  );
}
